SELECT MIN(settlement_id) AS settlement_id, merchant_id, merchant_name, business_number, settlement_month, MAX(status_changed_at) AS status_changed_at, SUM(settlement_amount) AS settlement_amount, MIN(status) AS status, MAX(created_at) AS created_at, MAX(updated_at) AS updated_at FROM settlement
AND settlement_month >= #{startMonth}
AND settlement_month <= #{endMonth}
AND status = #{status}
AND merchant_name LIKE CONCAT('%', #{merchantName}, '%')
AND business_number = #{businessNumber}
GROUP BY merchant_id, merchant_name, business_number, settlement_month ORDER BY settlement_month DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM (
SELECT merchant_id, settlement_month
FROM settlement


        AND settlement_month >= #{startMonth}


        AND settlement_month <= #{endMonth}


        AND status = #{status}


        AND merchant_name LIKE CONCAT('%', #{merchantName}, '%')


        AND business_number = #{businessNumber}


GROUP BY merchant_id, settlement_month
) AS sub

